SELECT COALESCE(SUM(CASE WHEN result = 1 THEN 1 ELSE 0 END), 0) AS helpful_count, COALESCE(SUM(CASE WHEN result = 2 THEN 1 ELSE 0 END), 0) AS unsolved_count, COUNT(*) AS total_count FROM ai_chat_feedback
update_time >= #{beginTime}
AND update_time < #{endExclusive}

SELECT id, session_id, user_id, result, handle_status, handler_id, handle_time, create_time, update_time FROM ai_chat_feedback WHERE result = 2
AND update_time >= #{beginTime}
AND update_time < #{endExclusive}
AND handle_status <> 2 ORDER BY update_time DESC, id DESC

